"""
Subsample 1,200 evaluation sets from the 6,000 grade-balanced alignment.
Skips re-running Stage 1's expensive TF-IDF alignment.
"""
import json, sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")
from pathlib import Path
from collections import defaultdict

import pandas as pd

STAGE1 = Path("output/stage1")

# Load the 6k grade-balanced data (already generated by user)
eval_6k = pd.read_csv(STAGE1 / "kutub_sitta_evaluation_6000_grade_balanced.csv")
align_6k = json.load(open(STAGE1 / "alignment_results_6000_grade_balanced.json", encoding="utf-8"))

# Build lookup for book_key per query_idx in the 6k eval set
idx_to_book = eval_6k["book_key"].to_dict()
idx_to_grade = eval_6k["grade_normalised"].to_dict()

# ── 1,200 Book-Balanced: 300 per book from 6k alignment ──
print("=== Building 1,200 Book-Balanced ===")
book_groups = defaultdict(list)
for entry in align_6k:
    if not entry.get("is_match"): continue
    qidx = int(entry["query_idx"])
    book = idx_to_book.get(qidx)
    if book:
        book_groups[book].append(entry)

# Take 300 per book
book_sample = []
book_counts = {}
for book in ["bukhari", "muslim", "abudawud", "tirmidhi", "nasai", "ibnmajah"]:
    entries = book_groups.get(book, [])
    taken = entries[:300]
    book_sample.extend(taken)
    book_counts[book] = len(taken)
    print(f"  {book:15s}: {len(taken)} / {len(entries)} available")

# Build evaluation CSV from query_idx values
used_idxs_bb = sorted(set(int(e["query_idx"]) for e in book_sample))
eval_1200_bb = eval_6k.iloc[used_idxs_bb].reset_index(drop=True)
eval_1200_bb.to_csv(STAGE1 / "kutub_sitta_evaluation_1200_book_balanced.csv", index=False)
print(f"  Saved evaluation CSV: {len(eval_1200_bb)} rows")

# Update query_idx to match new 0-based index
old_to_new_bb = {old: new for new, old in enumerate(used_idxs_bb)}
align_1200_bb = []
for entry in book_sample:
    new_entry = dict(entry)
    new_entry["query_idx"] = old_to_new_bb[int(entry["query_idx"])]
    align_1200_bb.append(new_entry)
json.dump(align_1200_bb, open(STAGE1 / "alignment_results_1200_book_balanced.json", "w", encoding="utf-8"), indent=2)
matched_bb = sum(1 for e in align_1200_bb if e.get("is_match"))
print(f"  Saved alignment: {len(align_1200_bb)} entries, {matched_bb} matched")
print(f"  Total: {sum(book_counts.values())} chains")

# ── 1,200 Grade-Balanced: up to 450 per grade from 6k alignment ──
print("\n=== Building 1,200 Grade-Balanced ===")
grade_groups = defaultdict(list)
for entry in align_6k:
    if not entry.get("is_match"): continue
    qidx = int(entry["query_idx"])
    grade = idx_to_grade.get(qidx)
    if grade:
        grade_groups[grade].append(entry)

# Take up to 450 per grade
GRADE_NAMES = ["Sahih", "Hasan", "Daif", "Matruk"]
GRADE_LOOKUP = {"Sahih": "Sahih", "Hasan": "Hasan", "Daif": "Daif", "Matruk": "Matruk"}
# Map from actual CSV values to our keys
actual_grades = list(grade_groups.keys())
print(f"  Found grades in data: {actual_grades}")

grade_sample = []
grade_counts = {}
# Match actual grade labels from the CSV
for actual_grade in actual_grades:
    taken = grade_groups[actual_grade][:450]
    grade_sample.extend(taken)
    grade_counts[actual_grade] = len(taken)
    print(f"  {actual_grade:15s}: {len(taken)} / {len(grade_groups[actual_grade])} available")

used_idxs_gb = sorted(set(int(e["query_idx"]) for e in grade_sample))
eval_1200_gb = eval_6k.iloc[used_idxs_gb].reset_index(drop=True)
eval_1200_gb.to_csv(STAGE1 / "kutub_sitta_evaluation_1200_grade_balanced.csv", index=False)
print(f"  Saved evaluation CSV: {len(eval_1200_gb)} rows")

old_to_new_gb = {old: new for new, old in enumerate(used_idxs_gb)}
align_1200_gb = []
for entry in grade_sample:
    new_entry = dict(entry)
    new_entry["query_idx"] = old_to_new_gb[int(entry["query_idx"])]
    align_1200_gb.append(new_entry)
json.dump(align_1200_gb, open(STAGE1 / "alignment_results_1200_grade_balanced.json", "w", encoding="utf-8"), indent=2)
matched_gb = sum(1 for e in align_1200_gb if e.get("is_match"))
print(f"  Saved alignment: {len(align_1200_gb)} entries, {matched_gb} matched")
print(f"  Total: {sum(grade_counts.values())} chains")

print("\nDone! All 4 evaluation datasets ready.")
